public class DuplicateDetection {
    // Classic algorithm: find first duplicate in O(n) time, O(n) space
    public static Long findFirstDuplicate(List<Long> orderIds) {
        var seen = new HashSet<Long>();
        for (var id : orderIds) {
            if (!seen.add(id)) {  // add returns false = duplicate found
                return id;
            }
        }
        return null;  // no duplicates
    }

    public static void main(String[] args) {
        var orders = List.of(101L, 102L, 103L, 102L, 104L);
        Long firstDup = findFirstDuplicate(orders);
        System.out.println("First duplicate: " + firstDup); // 102

        // Common mistake: unnecessary contains check
        var processed = new HashSet<Long>();
        for (var id : orders) {
            if (!processed.contains(id)) {  // WASTEFUL: first operation
                processed.add(id);           // second operation
                System.out.println("Processing: " + id);
            }
        }

        // Efficient version: single operation
        var efficientProcessed = new HashSet<Long>();
        for (var id : orders) {
            if (efficientProcessed.add(id)) {  // One call, check return value
                System.out.println("Processing: " + id);
            }
        }
    }
}

