public class OrderIdSet {
    public static void main(String[] args) {
        var orderIds = new HashSet<Long>();

        // Behind the scenes: map.put(101L, PRESENT)
        boolean added1 = orderIds.add(101L);
        System.out.println("Added 101: " + added1); // true

        // Attempting to add duplicate: map.put returns existing PRESENT
        boolean added2 = orderIds.add(101L);
        System.out.println("Added 101 again: " + added2); // false

        orderIds.add(null); // Allowed, becomes null key in internal HashMap
        System.out.println("Contains null: " + orderIds.contains(null)); // true

        // Custom object requires proper hashCode/equals
        record Order(Long id, String item) {}
        var orders = new HashSet<Order>();
        var order = new Order(101L, "Laptop");
        orders.add(order);
        // Record auto-generates hashCode/equals, so this works correctly
        System.out.println(orders.contains(new Order(101L, "Laptop"))); // true
    }
}

public class CustomSortedOrders {
    record Order(Long id, String item, int priority) {}

    public static void main(String[] args) {
        // Sort by priority (high to low), then by ID (low to high)
        var ordersByPriority = new TreeSet<Order>(
            Comparator.comparingInt(Order::priority).reversed()
                      .thenComparingLong(Order::id)
        );

        ordersByPriority.add(new Order(101L, "Laptop", 1));
        ordersByPriority.add(new Order(102L, "Mouse", 3));
        ordersByPriority.add(new Order(103L, "Keyboard", 3));

        // Iterates in custom order: priority 3 items first, then priority 1
        ordersByPriority.forEach(System.out::println);

        // DANGER: Comparator that treats different objects as equal
        var byPriorityOnly = new TreeSet<Order>(
            Comparator.comparingInt(Order::priority)
        );
        byPriorityOnly.add(new Order(101L, "Laptop", 1));
        byPriorityOnly.add(new Order(102L, "Mouse", 1)); // REJECTED! Same priority = duplicate
        System.out.println("Size: " + byPriorityOnly.size()); // 1, not 2
    }
}
